Readers.CommandLine:
"C:\Program Files\PowerShell\7\pwsh.exe" -Command "try { [Console]::OutputEncoding=[System.Text.Encoding]::UTF8 } catch {}
$ErrorActionPreference = 'Stop'
if ($PSVersionTable.PSVersion.Major -lt 7) { throw 'PowerShell 7 required' }
$reviewClock = [Diagnostics.Stopwatch]::StartNew()
$reviewRoot = 'D:\source\Sezika\.artifacts\label-audit-20261008'
$readerPath = Join-Path $reviewRoot 'script-review-final-readers.json'
$cancelPath = Join-Path $reviewRoot 'script-review-final.cancel.request'
if (Test-Path -LiteralPath $readerPath) { throw 'Final reader manifest exists; preserving it' }
$taskProcess = Get-CimInstance -ClassName Win32_Process -Filter \"ProcessId = $PID\" -OperationTimeoutSec 10
$identity = [ordered]@{ Pid = $PID; Started = $taskProcess.CreationDate.ToString('o'); CommandLine = $taskProcess.CommandLine; ParentPid = [int]$taskProcess.ParentProcessId; Role = 'reader'; MaximumFiles = 3; MaximumSeconds = 240; Completed = $null; ElapsedSeconds = $null }
$evidence = [ordered]@{ Readers = @($identity); Files = @(); Writers = @() }
function Read-ReviewFile([string]$Name) {
    if ($reviewClock.Elapsed.TotalSeconds -ge 240) { throw 'Review wall time exceeded' }
    if (Test-Path -LiteralPath $cancelPath) { throw 'Review canceled' }
    $filePath = Join-Path $reviewRoot $Name
    $info = Get-Item -LiteralPath $filePath
    if ($info.Length -gt 131072) { throw 'File exceeds 128 KiB review cap' }
    $fileLines = [IO.File]::ReadAllLines($filePath)
    if ($fileLines.Length -gt 800) { throw 'File exceeds 800-line review cap' }
    $hash = (Get-FileHash -LiteralPath $filePath -Algorithm SHA256).Hash
    $evidence.Files += [ordered]@{ Path = $filePath; Sha256 = $hash; Lines = $fileLines.Length; Bytes = $info.Length }
    Write-Output ('FILE=' + $filePath + '; SHA256=' + $hash + '; Lines=' + $fileLines.Length)
    $fileLines | ForEach-Object -Begin { $reviewLineNumber = 0 } -Process { if ($reviewClock.Elapsed.TotalSeconds -ge 240 -or (Test-Path -LiteralPath $cancelPath)) { throw 'Review time/cancellation bound' }; $reviewLineNumber += 1; '{0}: {1}' -f $reviewLineNumber, $_ }
}
try {
    $evidence | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $readerPath -Encoding utf8NoBOM
    Write-Output ('PSVersion=' + $PSVersionTable.PSVersion.ToString() + '; Progress=reading 3 fixed files')
    Read-ReviewFile 'Invoke-LabelAuditBatch.ps1'
    Read-ReviewFile 'Test-LabelAuditPayload.ps1'
    Read-ReviewFile 'validator-offline.result.json'
} finally {
    $identity.Completed = [DateTimeOffset]::Now.ToString('o')
    $identity.ElapsedSeconds = $reviewClock.Elapsed.TotalSeconds
    $evidence | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $readerPath -Encoding utf8NoBOM
    Write-Output ('ReaderIdentity=' + $readerPath + '; PID=' + $identity.Pid + '; Started=' + $identity.Started + '; ParentPid=' + $identity.ParentPid + '; ElapsedSeconds=' + $identity.ElapsedSeconds)
    # No child workload or temporary files were created.
}
"
